package com.alsafa.native4;import android.app.Activity;import android.content.Intent;import android.view.View;/** Legacy five-item navigation; each destination is a real Activity. */public final class Nav5{private Nav5(){}public static void bind(Activity a,int current){go(a,R.id.navHome,AdvancedHomeActivity.class,current);go(a,R.id.navSale,SaleActivity.class,current);go(a,R.id.navRepair,RepairActivity.class,current);go(a,R.id.navSearch,SearchActivity.class,current);go(a,R.id.navMore,MoreActivity.class,current);}private static void go(Activity a,int id,Class<?> c,int current){View v=a.findViewById(id);if(v==null)return;v.setEnabled(id!=current);if(id!=current)v.setOnClickListener(x->{Intent i=new Intent(a,c);i.addFlags(Intent.FLAG_ACTIVITY_REORDER_TO_FRONT);a.startActivity(i);});}}